SELECT 'batch_018_89b22aec_wav_11' AS batch_id,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-22e86a0b11974fe4915430f2119da7c4','sm-4d0d004dd8d74ebaadc851d5efab5525','sm-be8ba6dfd67f4f9a91bdb33b44d41d3a','sm-cdeaab57721d46afb6365cca2b0a146f','sm-e23ea8bf9f4846d7bfbda205e7b09672','sm-f9ae632a2ba14540a099fbb663bd3750','sm-upload-152098f7-f9e','sm-upload-2207d12c-443','sm-upload-3d0dfe07-125','sm-upload-abf7fe3c-d54','sm-upload-ce73a06c-13b') AND album_id='al-0f93c4e539eb79562fce224989b22aec') AS candidate_masters_in_target,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-22e86a0b11974fe4915430f2119da7c4','sm-4d0d004dd8d74ebaadc851d5efab5525','sm-be8ba6dfd67f4f9a91bdb33b44d41d3a','sm-cdeaab57721d46afb6365cca2b0a146f','sm-e23ea8bf9f4846d7bfbda205e7b09672','sm-f9ae632a2ba14540a099fbb663bd3750','sm-upload-152098f7-f9e','sm-upload-2207d12c-443','sm-upload-3d0dfe07-125','sm-upload-abf7fe3c-d54','sm-upload-ce73a06c-13b') AND album_id='pending-uploads') AS candidate_masters_still_pending,(SELECT COUNT(*) FROM albums WHERE id='al-0f93c4e539eb79562fce224989b22aec' AND name='黑白') AS target_album_rows,(SELECT song_count FROM albums WHERE id='al-0f93c4e539eb79562fce224989b22aec') AS stored_song_count,(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-0f93c4e539eb79562fce224989b22aec') AS calculated_size;
